import RNA
import random
import sys

target = '......(.((((.((((....(...((((.(....).))))...)))))..((......((((....)))))).)))).).....................'
n = len(target)

def pairmap(ss):
    stack=[]
    pm=[-1]*len(ss)
    for i,c in enumerate(ss):
        if c=='(': stack.append(i)
        elif c==')':
            j=stack.pop()
            pm[i]=j; pm[j]=i
    return pm
pm = pairmap(target)

# positions that are paired in target
paired_pos = [i for i in range(n) if target[i] in '()']
unpaired_pos = [i for i in range(n) if target[i]=='.']

def fold_mfe(seq):
    fc = RNA.fold_compound(seq)
    ss, mfe = fc.mfe()
    return ss, mfe

def bp_dist(ss):
    # bp distance to target: count of pairs in target not in ss + pairs in ss not in target
    pm_ss = pairmap(ss)
    missing = 0
    for i in range(n):
        if pm[i]>=0:
            if pm_ss[i]!=pm[i]:
                missing+=1
    missing//=2
    spurious = 0
    for i in range(n):
        if pm_ss[i]>=0 and pm[i]<0:
            spurious+=1
    spurious//=2
    return missing+spurious

def random_init():
    seq = ['A']*n
    for i,c in enumerate(target):
        if c=='(':
            j=pm[i]
            r = random.random()
            if r<0.5: seq[i]='G'; seq[j]='C'
            else: seq[i]='C'; seq[j]='G'
    return ''.join(seq)

def mutate(seq, k=1):
    s=list(seq)
    # mutate at paired or unpaired positions
    for _ in range(k):
        i = random.randint(0,n-1)
        if target[i] in '()':
            j=pm[i]
            # flip pair type among GC/CG/AU/UA/GU/UG
            choices = [('G','C'),('C','G'),('A','U'),('U','A'),('G','U'),('U','G')]
            # bias toward GC
            if random.random()<0.6:
                choices = [('G','C'),('C','G')]
            a,b = random.choice(choices)
            s[i]=a; s[j]=b
        else:
            s[i]=random.choice('ACGU')
    return ''.join(s)

def score(seq):
    ss,mfe = fold_mfe(seq)
    d = bp_dist(ss)
    return d, ss

best_overall = None
best_d = 999
import time
t0=time.time()
random.seed(42)
for restart in range(2000):
    seq = random_init()
    cur_d, cur_ss = score(seq)
    cur_seq = seq
    if cur_d < best_d:
        best_d = cur_d; best_overall = cur_seq
        if best_d==0:
            print('SOLVED at restart',restart); break
    # local search
    for step in range(400):
        cand = mutate(cur_seq, k=random.choice([1,1,2]))
        d,ss = score(cand)
        if d <= cur_d:
            if d < cur_d or random.random()<0.3:
                cur_d=d; cur_seq=cand
                if d < best_d:
                    best_d=d; best_overall=cand
                    if best_d==0:
                        print('SOLVED at restart',restart,'step',step); 
    if best_d==0: break
    if time.time()-t0 > 120: 
        print('time up at restart',restart); break

print('best_d',best_d)
print('best_seq',best_overall)
ss,mfe = fold_mfe(best_overall)
print('mfe',ss)
print('tgt',target)
